<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/functions.php';
$u=require_auth();
if(!is_admin($u)){ http_response_code(403); exit('Acesso negado.'); }
$version=PANEL_VERSION;
$manifestUrl=PANEL_UPDATE_MANIFEST_URL;
?>
<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atualização do Painel · ConnectPlus</title><link rel="stylesheet" href="/assets/css/style.css?v=3"><style>
.update-wrap{max-width:900px;margin:0 auto;padding:1.25rem}.update-card{margin-top:1rem}.version-box{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.8rem}.version-item{padding:1rem;border:1px solid rgba(148,163,184,.16);border-radius:.85rem;background:rgba(15,23,42,.5)}.version-label{display:block;color:#94a3b8;font-size:.72rem;text-transform:uppercase;font-weight:800;letter-spacing:.08em;margin-bottom:.35rem}.version-value{font-size:1.15rem;font-weight:800;color:#f8fafc}.update-log{white-space:pre-wrap;line-height:1.55;color:#cbd5e1}.update-status{margin-top:.9rem}.danger-note{padding:.9rem 1rem;border:1px solid rgba(251,191,36,.25);background:rgba(120,53,15,.16);border-radius:.8rem;color:#fcd34d}.success{color:#34d399}.error{color:#fb7185}@media(max-width:640px){.version-box{grid-template-columns:1fr}.update-wrap{padding:.85rem}}
</style></head><body class="dashboard-body"><main class="main-content" style="margin-left:0;min-height:100vh"><div class="update-wrap">
<div class="page-header"><div><div class="eyebrow">ADMINISTRAÇÃO</div><h1 class="page-title">Atualização do Painel</h1><p class="text-muted">Atualize o ConnectPlus online sem substituir manualmente os arquivos.</p></div><div style="display:flex;gap:.5rem;flex-wrap:wrap"><a class="btn secondary" href="/admin/dashboard.php">Voltar</a><a class="btn danger" href="/logout.php">Sair</a></div></div>
<div class="config-card update-card"><div class="version-box"><div class="version-item"><span class="version-label">Versão instalada</span><span class="version-value"><?=e($version)?></span></div><div class="version-item"><span class="version-label">Servidor de atualizações</span><span class="version-value" style="font-size:.85rem;word-break:break-all"><?=e($manifestUrl!==''?$manifestUrl:'Não configurado')?></span></div></div>
<div class="danger-note" style="margin-top:1rem">Antes de atualizar, o sistema cria um backup dos arquivos alterados e dos dados do banco. O arquivo <code>.env</code>, uploads e dados dos usuários não são sobrescritos pelo pacote.</div>
<div style="display:flex;gap:.6rem;flex-wrap:wrap;margin-top:1rem"><button class="btn secondary" id="checkBtn">Verificar atualização</button><button class="btn primary" id="updateBtn" style="display:none">Atualizar agora</button></div>
<div id="status" class="update-status text-muted"></div><div id="details" style="display:none;margin-top:1rem"><h3 class="section-title">Detalhes</h3><p><strong>Versão:</strong> <span id="remoteVersion">—</span></p><p><strong>SHA-256:</strong> <code id="sha">—</code></p><div><strong>Notas:</strong><div id="changelog" class="update-log" style="margin-top:.4rem"></div></div></div>
</div></div></main><script>
let release=null;
const manifestUrl=<?=json_encode($manifestUrl,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?>;
const $=id=>document.getElementById(id);
async function check(){ $('checkBtn').disabled=true;$('updateBtn').style.display='none';$('details').style.display='none';$('status').className='update-status text-muted';$('status').textContent='Consultando servidor de atualização...'; if(manifestUrl===''){$('status').className='update-status error';$('status').textContent='Servidor de atualizações não configurado no .env.';return;}try{const r=await fetch('/api/panel-update-check.php?ts='+Date.now(),{cache:'no-store',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Falha ao verificar');release=d.release||null;if(!release){$('status').textContent='Nenhuma atualização disponível.';return;} $('details').style.display='block';$('remoteVersion').textContent=release.version||'—';$('sha').textContent=release.sha256||'—';$('changelog').textContent=release.changelog||'Sem changelog.';if(d.updateAvailable){$('status').className='update-status success';$('status').textContent='Nova versão disponível.';$('updateBtn').style.display='inline-flex';}else{$('status').textContent='O painel já está na versão mais recente.';}}catch(e){$('status').className='update-status error';$('status').textContent=e.message||'Erro';}finally{$('checkBtn').disabled=false;}}
async function update(){if(!release)return;if(!confirm('Fazer backup e atualizar o painel agora?'))return;$('updateBtn').disabled=true;$('checkBtn').disabled=true;$('status').className='update-status text-muted';$('status').textContent='Atualizando... Não feche esta página.';try{const r=await fetch('/api/panel-update.php',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({version:release.version})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Falha na atualização');$('status').className='update-status success';$('status').textContent=d.message||'Painel atualizado. Recarregando...';setTimeout(()=>location.reload(),2500);}catch(e){$('status').className='update-status error';$('status').textContent=e.message||'Erro';$('updateBtn').disabled=false;$('checkBtn').disabled=false;}}
$('checkBtn').onclick=check;$('updateBtn').onclick=update;
window.addEventListener('error',e=>{$('status').className='update-status error';$('status').textContent='Erro no JavaScript: '+(e.message||'erro desconhecido');});
check();
</script></body></html>
